ee:message.ee:set-payload:
%dw 2.0
output text/xml
fun appendNamespace(data, nsSelector: (k: Key) -> Namespace | Null) =
  data match {
	case is Array -> data map appendNamespace($, nsSelector)
    case is Object -> data mapObject do {
		var ns0 = nsSelector($$)
		---
		ns0#"$($$)": appendNamespace($, nsSelector)
	}
    else -> data
}
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns ns2 http://soap.sforce.com/schemas/class/IntegracionRemedy_ws
---
soapenv#Envelope: {
    soapenv#Header: {
        SessionHeader:
            sessionId: vars.token_response.access_token
    },
    soapenv#Body: {
        ns2#WSActualizarObjeto: {
            ns2#mensajeEntrada: {
                (payload appendNamespace ns2)
            }
        }
    }
}
